-- 003-seed-profiles.sql
-- Seeds 50 prominent Iranian political and public figures as profiles.
-- Safe to run multiple times (ON CONFLICT (promtic_identifier->>'external_id') DO NOTHING via unique index).
-- Run AFTER 002-admin-migration.sql.

BEGIN;

-- Temporary unique index on external_id to make upsert safe
CREATE UNIQUE INDEX IF NOT EXISTS idx_profiles_promtic_ext_id
  ON profiles ((promtic_identifier->>'external_id'))
  WHERE promtic_identifier IS NOT NULL;


ON CONFLICT ((promtic_identifier->>'external_id')) DO NOTHING;

COMMIT;
